"""Blender finish/bake of approved F frame generated by Meshy.
Run blender -b --python tools/art/render_noble_crest.py.
The downloaded source remains in ignored artifacts; see assets/ui/persistent-home.
"""
import bpy
from pathlib import Path
from mathutils import Vector
root=Path(__file__).resolve().parents[2]
work=root/'artifacts/meshy/noble-crest-v1'
bpy.ops.wm.read_factory_settings(use_empty=True)
bpy.ops.import_scene.gltf(filepath=str(work/'download/model.glb'))
scene=bpy.context.scene
frame=next(o for o in scene.objects if o.type=='MESH')
frame.name='NobleCrest_MeshyCarvedIvory'
# Preserve Meshy's relief and PBR UVs. No source-image projection or replacement mesh.
for poly in frame.data.polygons: poly.use_smooth=True
bpy.ops.object.camera_add(location=(0,-5,0))
camera=bpy.context.object;camera.name='Orthographic_UI_Bake'
camera.rotation_euler=(Vector((0,0,0))-camera.location).to_track_quat('-Z','Y').to_euler()
camera.data.type='ORTHO';camera.data.ortho_scale=2.025;scene.camera=camera
for name,location,power,size,color in [
 ('IvoryKey',(-2,-3,3),380,3.5,(1,.97,.91)),
 ('CoolFill',(2,-2,1),160,3,(.88,.94,1)),
 ('LowerRelief',(-1,-1,-2),40,2,(1,1,1))]:
 bpy.ops.object.light_add(type='AREA',location=location)
 lamp=bpy.context.object;lamp.name=name;lamp.data.energy=power;lamp.data.shape='DISK';lamp.data.size=size;lamp.data.color=color
 lamp.rotation_euler=(Vector((0,0,0))-lamp.location).to_track_quat('-Z','Y').to_euler()
scene.world=bpy.data.worlds.new('NeutralStudio');scene.world.use_nodes=True
scene.world.node_tree.nodes['Background'].inputs['Color'].default_value=(.7,.75,.8,1)
scene.world.node_tree.nodes['Background'].inputs['Strength'].default_value=.25
scene.render.engine='CYCLES';scene.cycles.samples=64;scene.cycles.use_denoising=True
scene.render.resolution_x=1536;scene.render.resolution_y=2150;scene.render.resolution_percentage=100
scene.render.film_transparent=True
scene.view_settings.view_transform='AgX'
scene.render.image_settings.file_format='PNG';scene.render.image_settings.color_mode='RGBA';scene.render.image_settings.color_depth='8'
scene.render.filepath=str(root/'src/L5R.Client/Art/PersistentHome/noble-crest-meshy.png')
# This self-contained authoring source is archived privately, not bundled in the game.
bpy.ops.file.pack_all()
bpy.ops.wm.save_as_mainfile(filepath=str(work/'noble-crest-finished.blend'))
bpy.ops.render.render(write_still=True)
